// Cloudflare entry point: the Next.js app built by OpenNext, plus the cron trigger that sends Telegram reminders.
// `.open-next/worker.js` is generated by `npm run cf:build`.
import handler from "../.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_controller, env, ctx) {
    const headers = env.CRON_SECRET ? { authorization: `Bearer ${env.CRON_SECRET}` } : {};
    const req = new Request("https://cron.internal/api/cron/notify", { headers });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (r) => {
        if (!r.ok) console.warn("cron.notify", r.status, await r.text().catch(() => ""));
      }),
    );
  },
};
